package com.procurement.goodsreceipt.entity;import com.procurement.purchaseorder.entity.PurchaseOrder;import com.procurement.vendor.entity.Vendor;import com.procurement.warehouse.entity.Warehouse;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity@Table(name="goods_receipt_notes",uniqueConstraints=@UniqueConstraint(columnNames="grn_number"))@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class GoodsReceiptNote{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="grn_id")private Long id;@Column(name="grn_number",nullable=false,length=40)private String grnNumber;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="purchase_order_id",nullable=false)private PurchaseOrder purchaseOrder;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="vendor_id",nullable=false)private Vendor vendor;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="warehouse_id",nullable=false)private Warehouse warehouse;@Column(name="received_by",nullable=false)private String receivedBy;@Column(name="inspection_by")private String inspectionBy;@Column(name="receipt_date",nullable=false)private LocalDate receiptDate;@Column(name="invoice_reference")private String invoiceReference;@Column(name="vehicle_number")private String vehicleNumber;@Column(name="transporter_name")private String transporterName;@Column(length=1000)private String remarks;@Enumerated(EnumType.STRING)@Column(nullable=false,length=25)private GrnStatus status;@Column(name="created_by",nullable=false)private String createdBy;@Column(name="updated_by")private String updatedBy;@Column(name="created_at",updatable=false)private LocalDateTime createdAt;@Column(name="updated_at")private LocalDateTime updatedAt;@PrePersist void pre(){var n=LocalDateTime.now();createdAt=n;updatedAt=n;if(status==null)status=GrnStatus.DRAFT;}@PreUpdate void upd(){updatedAt=LocalDateTime.now();}}
